UPDATE HCP_API_SUB
SET SUB_STAT_CD = #{subStatCd},
    APRV_DTTM   = SYSDATE,
    APRV_REASON = #{aprvReason},
    UPD_DTTM    = SYSDATE
WHERE PUB_ID = #{pubId}
  AND KEY_ID = #{keyId}
  AND SUB_STAT_CD = #{beforeSubStatCd}

UPDATE HCP_API_EXPIRED_SYSEMPNO
SET UPDATED_AT    = SYSDATE,
    BATCH_STAT_CD = #{batchStatCd}
WHERE SYS_EMP_NO = #{sysEmpNo}
